use super::*;
fn observe<R>(run:impl FnOnce()->R)->(R,(usize,usize)){semio_framework_value_testing_allocator::observe_retirement_allocations(run)}
trait FixtureError:std::fmt::Debug{fn progress(&self)->RetainedCloneProgress;}
impl FixtureError for ValueError{fn progress(&self)->RetainedCloneProgress{self.retained_progress()}}
impl FixtureError for semio_framework_value_retirement::OriginalRetirementFailure{fn progress(&self)->RetainedCloneProgress{self.retained_progress()}}
struct Bank{g:RetainedCloneGrant,fuel:u128}
impl Bank{fn new(f:&serde_json::Value)->Self{Self{g:RetainedCloneGrant{maximum_items:f["items"].as_u64().unwrap()as usize,maximum_copy_bytes:f["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:f["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:f["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:f["depth"].as_u64().unwrap()as usize},fuel:u128::from(f["fuel"].as_u64().unwrap())}}fn loan(&self,d:RetirementDemand)->RetainedCloneGrant{assert!(retained_clone_grant_admits(self.g,d));RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}fn post<E:FixtureError>(&mut self,turn:RetainedWorkOutcome<RetainedCloneStep,E>)->RetainedCloneStep{let p=match&turn.result{Ok(s)=>s.progress(),Err(e)=>e.progress()};assert!(p.fits(self.g));self.g.maximum_items-=p.copied_items;self.g.maximum_copy_bytes-=p.copied_bytes;self.g.maximum_capacity_bytes-=p.retained_capacity_bytes;self.g.maximum_release_bytes-=p.released_bytes;self.fuel=self.fuel.checked_sub(turn.work).unwrap();turn.result.unwrap()}}
#[test]fn actual_inline_prefix_moves_rows_and_cancellation_without_default_or_heap(){let f:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let mut bank=Bank::new(&f["stock"]);let(mut empty,heap)=observe(NativeOwnedPrefix::<u64,0>::empty);assert_eq!(heap,(0,0));assert!(empty.as_slice().is_empty());let mut input=Some(17);let turn=empty.push_from(&mut input,bank.loan(NativeOwnedPrefix::<u64,0>::push_demand()));assert_eq!(turn.work,0);assert!(turn.result.is_err());assert_eq!(input,Some(17));assert!(empty.is_empty());
 let(mut rows,heap)=observe(NativeOwnedPrefix::<u64,3>::empty);assert_eq!(heap,(0,0));let expected:Vec<u64>=serde_json::from_value(f["cases"][1]["values"].clone()).unwrap();for value in&expected{let mut input=Some(*value);let d=NativeOwnedPrefix::<u64,3>::push_demand();assert_eq!(d.copy_bytes,f["ownedPushCopyBytes"].as_u64().unwrap()as usize);let g=bank.loan(d);for denied in[Some(RetainedCloneGrant{maximum_items:0,..g}),(d.copy_bytes>0).then(||RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g}),Some(RetainedCloneGrant{maximum_depth:0,..g})].into_iter().flatten(){let(turn,heap)=observe(||rows.push_from(&mut input,denied));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(input,Some(*value));assert_eq!(heap,(0,0));}let(turn,heap)=observe(||rows.push_from(&mut input,g));assert_eq!(turn.work,1);assert_eq!(heap,(0,0));assert_eq!(bank.post(turn).progress().copied_bytes,f["ownedPushCopyBytes"].as_u64().unwrap()as usize);assert!(input.is_none());}assert_eq!(serde_json::to_value(rows.as_slice()).unwrap(),serde_json::to_value(&expected).unwrap());let g=bank.loan(NativeOwnedPrefix::<u64,3>::move_demand());let(turn,heap)=observe(||rows.swap(0,2,g));assert_eq!(turn.work,1);assert_eq!(heap,(0,0));assert_eq!(bank.post(turn).progress().copied_bytes,0);let turn=rows.swap(0,0,g);assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());let mut actual=Vec::new();while !rows.is_empty(){let mut output=None;let g=bank.loan(NativeOwnedPrefix::<u64,3>::move_demand());let(turn,heap)=observe(||rows.pop_into(&mut output,RetainedCloneGrant{maximum_items:0,..g}));assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert!(output.is_none());assert_eq!(heap,(0,0));let(turn,heap)=observe(||rows.pop_into(&mut output,g));assert_eq!(turn.work,1);assert_eq!(heap,(0,0));assert_eq!(bank.post(turn).progress().copied_bytes,0);actual.push(output.unwrap());}assert_eq!(actual,vec![17,23,31]);let mut output=None;assert_eq!(rows.pop_into(&mut output,Default::default()).work,0);assert_eq!(observe(||drop(rows)).1,(0,0));}
#[test]fn actual_inline_prefix_zero_sized4097_rows_never_collapse_into_one_callback(){let f:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let mut bank=Bank::new(&f["stock"]);let(mut rows,heap)=observe(NativeOwnedPrefix::<(),4097>::empty);assert_eq!(heap,(0,0));let mut work=0;for count in 0..4097{let mut input=Some(());let g=bank.loan(NativeOwnedPrefix::<(),4097>::push_demand());let(turn,heap)=observe(||rows.push_from(&mut input,g));work+=turn.work;assert_eq!(turn.work,1);assert_eq!(heap,(0,0));assert_eq!(bank.post(turn).progress().copied_bytes,0);assert_eq!(rows.len(),count+1);}assert_eq!(work,4097);assert_eq!(rows.as_slice().len(),4097);while !rows.is_empty(){let mut output=None;let g=bank.loan(NativeOwnedPrefix::<(),4097>::move_demand());let(turn,heap)=observe(||rows.pop_into(&mut output,g));work+=turn.work;assert_eq!(turn.work,1);assert_eq!(heap,(0,0));bank.post(turn);assert_eq!(output,Some(()));}assert_eq!(work,8194);assert_eq!(observe(||drop(rows)).1,(0,0));}

#[test]fn actual_inline_prefix_owned_string_moves_keep_the_original_body_and_report_zero_copy(){
 let f:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let mut bank=Bank::new(&f["stock"]);let mut input=Some(f["ownedText"].as_str().unwrap().to_owned());let pointer=input.as_ref().unwrap().as_ptr();let mut rows=NativeOwnedPrefix::<String,1>::empty();let d=NativeOwnedPrefix::<String,1>::push_demand();assert_eq!(d.copy_bytes,f["ownedPushCopyBytes"].as_u64().unwrap()as usize);let g=bank.loan(d);
 for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let(turn,heap)=observe(||rows.push_from(&mut input,denied));assert_eq!(turn.work,0);assert_eq!(heap,(0,0));assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(input.as_ref().unwrap().as_ptr(),pointer);assert!(rows.is_empty());}
 let(turn,heap)=observe(||rows.push_from(&mut input,g));assert_eq!(turn.work,1);assert_eq!(heap,(0,0));assert_eq!(bank.post(turn).progress().copied_bytes,0);assert!(input.is_none());assert_eq!(rows.get(0).unwrap().as_ptr(),pointer);let mut output=None;let(turn,heap)=observe(||rows.pop_into(&mut output,bank.loan(NativeOwnedPrefix::<String,1>::move_demand())));assert_eq!(turn.work,1);assert_eq!(heap,(0,0));assert_eq!(bank.post(turn).progress().copied_bytes,0);assert_eq!(output.as_ref().unwrap().as_ptr(),pointer);assert_eq!(serde_json::to_value(output.as_ref().unwrap()).unwrap(),f["ownedText"]);assert_eq!(observe(||drop(rows)).1,(0,0));
 let Bank{g,fuel}=bank;let mut original=semio_framework_value_testing_effect_bank::EffectBank::new(semio_framework_value_testing_effect_bank::Wallet::new(g,u64::try_from(fuel).unwrap()));super::super::tests::cleanup::close(output.take().unwrap(),&mut original,10000);assert!(original.is_idle());
}
